// migrate.js
// Simple migration script that reads SQL files from ./migrations/ directory
// and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

// Resolve the migrations directory relative to this script
const migrationsDir = path.resolve(__dirname, 'migrations');

// Check if the directory exists
if (!fs.existsSync(migrationsDir)) {
  console.error(`Migrations directory not found: ${migrationsDir}`);
  process.exit(1);
}

// Read all files, filter for .sql extensions, and sort them alphabetically
const migrationFiles = fs
  .readdirSync(migrationsDir)
  .filter((file) => file.toLowerCase().endsWith('.sql'))
  .sort();

if (migrationFiles.length === 0) {
  console.log('No migration files found.');
  process.exit(0);
}

console.log('Migrations to apply (in order):');
for (const file of migrationFiles) {
  console.log(`- ${file}`);
}

