// migrate.js
// This script scans the ./migrations/ directory for SQL files,
// sorts them alphabetically (ensuring deterministic order), and logs
// each filename that would be applied. It does not actually execute
// any SQL; it merely demonstrates the order of migrations.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');

// Helper to check if a file has .sql extension (case-insensitive)
function isSqlFile(filename) {
  return path.extname(filename).toLowerCase() === '.sql';
}

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter only .sql files
    const sqlFiles = files.filter(isSqlFile);
    // Sort them alphabetically to enforce deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Error reading migrations directory at ${dir}:`, err.message);
    process.exit(1);
  }
}

function main() {
  const migrationFiles = getMigrationFiles(migrationsDir);
  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  migrationFiles.forEach((file) => {
    console.log(`- ${file}`);
  });
}

if (require.main === module) {
  main();
}

