    });
    if (!response.ok) {
      console.warn(`Audit service responded with status ${response.status}`);
    } else {
      console.log('✅ Environment audit posted successfully');
    }
  } catch (err) {
    console.warn('Failed to post environment audit:', err.message);
  }
}

