// migrate.js
// Simple migration script that reads SQL files from the ./migrations directory
// and logs each filename in the order they would be applied.
// The ordering is alphabetical (lexicographic) which works well when filenames
// are prefixed with timestamps or incremental numbers, e.g. "001_init.sql",
// "20230715_add_users.sql", etc.

const fs = require('fs');
const path = require('path');

// Directory containing migration files relative to this script
const migrationsDir = path.resolve(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    // Filter for regular files that end with .sql (case‑insensitive)
    const sqlFiles = entries
      .filter((e) => e.isFile() && e.name.toLowerCase().endsWith('.sql'))
      .map((e) => e.name);
    // Sort alphabetically to provide deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Unable to read migrations directory "${dir}":`, err.message);
    process.exit(1);
  }
}

function logMigrations() {
  const files = getSqlFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations to be applied (in order):');
  files.forEach((file) => {
    console.log(`- ${file}`);
  });
}

// Execute when run directly
if (require.main === module) {
  logMigrations();
}

module.exports = { getSqlFiles, logMigrations };

