```js
// migrate.js
// ---------------------------------------------------------------------
// Scans the ./migrations directory for .sql files, sorts them, and
// logs each filename that would be applied.
// ---------------------------------------------------------------------

const fs = require('fs');
const path = require('path');

// Path to the migrations directory (relative to this script)
const migrationsDir = path.join(__dirname, 'migrations');

// Helper: keep only files that end with .sql (case‑insensitive)
const isSqlFile = (filename) => /\.sql$/i.test(filename);

try {
  // Read the directory contents
  const allFiles = fs.readdirSync(migrationsDir);

  // Filter to .sql files and sort them alphabetically
  const sqlFiles = allFiles.filter(isSqlFile).sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
  } else {
    console.log('Migrations to apply (in order):');
    sqlFiles.forEach((file) => console.log('- ' + file));
  }
} catch (err) {
  // Most likely the migrations directory does not exist or cannot be read
  console.error('Error reading migrations directory:', err.message);
  process.exit(1);
}
```

