const envVars = parseEnvFile(envPath);

// Export to process.env for any downstream code that might rely on it
Object.assign(process.env, envVars);

// ---------------------------------------------------------------------
// 2️⃣ Send env vars to the audit service
// ---------------------------------------------------------------------
function postToAudit(data) {
  return new Promise((resolve, reject) => {
    const auditUrl = new URL('http://localhost:47301/api/audit');
    const payload = JSON.stringify(data);

    const options = {
      hostname: auditUrl.hostname,
      port:     auditUrl.port,
      path:     auditUrl.pathname,
      method:   'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(body);
        } else {
          reject(new Error(`Audit service responded with ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

// Fire the audit request (non‑blocking – we wait for it before proceeding)
(async () => {
  try {
    await postToAudit(envVars);
    console.log('✅ Audit log sent successfully.');
  } catch (err) {
    console.warn('⚠️  Failed to send audit log:', err.message);
  }

  // -----------------------------------------------------------------
  // 3️⃣ Fake DB connection message (using DATABASE_URL if present)
  // -----------------------------------------------------------------
  if (process.env.DATABASE_URL) {
    console.log(`🔗 Connected to database at ${process.env.DATABASE_URL}`);
  } else {
    console.warn('⚠️  DATABASE_URL not defined – cannot show connection message.');
  }

  // -----------------------------------------------------------------
  // 4️⃣ Scan ./migrations for .sql files and log the order
  // -----------------------------------------------------------------
  const migrationsDir = path.join(__dirname, 'migrations');
  const isSqlFile = (f) => /\.sql$/i.test(f);

  try {
    const allFiles = fs.readdirSync(migrationsDir);
    const sqlFiles = allFiles.filter(isSqlFile).sort();

    if (sqlFiles.length === 0) {
      console.log('No migration files found in', migrationsDir);
    } else {
      console.log('Migrations to apply (in order):');
      sqlFiles.forEach(f => console.log('- ' + f));
    }
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
})();
