// migrate.js
// Simple migration script that reads SQL files from ./migrations directory
// and logs each filename in the order they would be applied.

const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const migrationsDir = path.join(__dirname, 'migrations');

// Helper to get list of .sql files sorted alphabetically (or by numeric prefix if present)
function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter only .sql files
    const sqlFiles = files.filter((f) => f.endsWith('.sql'));
    // Sort: if files start with a numeric prefix (e.g., 001_init.sql) sort numerically,
    // otherwise fallback to plain alphabetical order.
    sqlFiles.sort((a, b) => {
      const aMatch = a.match(/^([0-9]+)_/);
      const bMatch = b.match(/^([0-9]+)_/);
      if (aMatch && bMatch) {
        return Number(aMatch[1]) - Number(bMatch[1]);
      }
      return a.localeCompare(b);
    });
    return sqlFiles;
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
}

function logMigrations() {
  const files = getMigrationFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }
  console.log('Migrations to be applied (in order):');
  files.forEach((file) => {
    console.log(' -', file);
  });
}

// Execute when the script is run directly
if (require.main === module) {
  logMigrations();
}

module.exports = {
  getMigrationFiles,
  logMigrations,
};

