// migrate.js
// This script reads SQL files from the ./migrations/ directory
// and logs each filename in the order they would be applied.
// It does NOT execute the SQL; it merely demonstrates the ordering logic.

const fs = require('fs');
const path = require('path');

(async () => {
  const migrationsDir = path.join(__dirname, 'migrations');
  try {
    // Read all entries in the migrations directory
    const files = await fs.promises.readdir(migrationsDir);
    // Filter only .sql files
    const sqlFiles = files.filter((file) => file.endsWith('.sql'));
    // Sort files alphabetically (common convention: prefix with numbers)
    sqlFiles.sort();
    if (sqlFiles.length === 0) {
      console.log('No migration files found in', migrationsDir);
      return;
    }
    console.log('Migrations to apply (in order):');
    for (const file of sqlFiles) {
      console.log('-', file);
    }
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('Migrations directory does not exist:', migrationsDir);
    } else {
      console.error('Error reading migrations:', err);
    }
    process.exit(1);
  }
})();

