// migrate.js
// This script reads SQL migration files from the ./migrations directory
// and logs each filename in the order they would be applied.
// The ordering is alphabetical, which works well if filenames are prefixed
// with timestamps or incremental numbers (e.g., 001_initial.sql, 002_add_user.sql).

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

// Helper: check if a file has .sql extension (case‑insensitive)
function isSqlFile(fileName) {
  return path.extname(fileName).toLowerCase() === '.sql';
}

try {
  // Read all entries in the migrations directory
  const entries = fs.readdirSync(migrationsDir, { withFileTypes: true });

  // Filter only regular files with .sql extension
  const sqlFiles = entries
    .filter((dirent) => dirent.isFile() && isSqlFile(dirent.name))
    .map((dirent) => dirent.name);

  // Sort filenames alphabetically (lexicographic)
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
  } else {
    console.log('Migrations to apply (in order):');
    sqlFiles.forEach((file) => {
      console.log('- ' + file);
    });
  }
} catch (err) {
  console.error('Error reading migrations directory:', err.message);
  process.exit(1);
}

