// migrate.js
// This script reads SQL migration files from the ./migrations/ directory
// and logs each filename in the order they would be applied. It also
// resolves a database connection string from .env.test and logs a
// simulated successful connection message.

const fs = require('fs');
const path = require('path');

// -------------------------------------------------------------------
// Resolve DATABASE_URL from .env.test (if present)
// -------------------------------------------------------------------
let databaseUrl = '';
try {
  const envPath = path.join(__dirname, '.env.test');
  const envContent = fs.readFileSync(envPath, { encoding: 'utf8' });
  envContent.split(/\r?\n/).forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return; // skip comments/blank
    const [key, ...rest] = trimmed.split('=');
    if (key === 'DATABASE_URL') {
      databaseUrl = rest.join('='); // preserve any '=' in the value
    }
  });
} catch (e) {
  // .env.test may not exist; ignore.
}

if (databaseUrl) {
  console.log('Successfully resolved DATABASE_URL from .env.test');
  console.log('Connected to database:', databaseUrl);
} else {
  console.warn('DATABASE_URL not found in .env.test');
}

// -------------------------------------------------------------------
// Migration handling
// -------------------------------------------------------------------
const migrationsDir = path.join(__dirname, 'migrations');

fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }

  // Filter only .sql files and sort them alphabetically
  const sqlFiles = files
    .filter(f => path.extname(f).toLowerCase() === '.sql')
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations to apply:');
  sqlFiles.forEach(f => console.log('- ' + f));
  // In a real implementation you would execute each SQL file here.
});

