// migrate.js
// This script reads SQL migration files from the ./migrations/ directory
// and logs each filename in the order they would apply. It also resolves
// a database connection string from .env.test, logs a simulated successful
// connection message, and posts the environment values to an audit service.

const fs = require('fs');
const path = require('path');
const http = require('http');

// -------------------------------------------------------------------
// Load .env.test values
// -------------------------------------------------------------------
const envPath = path.join(__dirname, '.env.test');
let envVars = {};
let databaseUrl = '';
try {
  const envContent = fs.readFileSync(envPath, { encoding: 'utf8' });
  envContent.split(/\r?\n/).forEach(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;
    const [key, ...rest] = trimmed.split('=');
    const value = rest.join('=');
    envVars[key] = value;
    if (key === 'DATABASE_URL') databaseUrl = value;
  });
} catch (e) {
  // .env.test may not exist; continue with empty envVars.
}

// -------------------------------------------------------------------
// Audit logging: POST envVars to the local audit service
// -------------------------------------------------------------------
function postAudit(data) {
  const json = JSON.stringify(data);
  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(json)
    }
  };

  const req = http.request(options, res => {
    // Consume response data to free up memory
    let body = '';
    res.on('data', chunk => (body += chunk));
    res.on('end', () => {
      console.log('Audit service responded with status', res.statusCode);
    });
  });

  req.on('error', err => {
    console.error('Failed to send audit data:', err.message);
  });

  req.write(json);
  req.end();
}

if (Object.keys(envVars).length > 0) {
  console.log('Successfully resolved environment variables from .env.test');
  postAudit(envVars);
} else {
  console.warn('No environment variables found in .env.test');
}

if (databaseUrl) {
  console.log('Connected to database:', databaseUrl);
} else {
  console.warn('DATABASE_URL not found in .env.test');
}

// -------------------------------------------------------------------
// Migration handling
// -------------------------------------------------------------------
const migrationsDir = path.join(__dirname, 'migrations');
fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }

  const sqlFiles = files
    .filter(f => path.extname(f).toLowerCase() === '.sql')
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations to apply:');
  sqlFiles.forEach(f => console.log('- ' + f));
});
